}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:36:\"Metatag values for the current page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:7:\"metatag\";}s:11:\"page-number\";a:2:{s:4:\"name\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:11:\"Page number\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:61:\"The page number of the current page when viewing paged lists.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}}s:5:\"query\";a:3:{s:4:\"name\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:18:\"Query string value\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:63:\"The value of a specific query string field of the current page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:7:\"dynamic\";b:1;}s:5:\"title\";a:2:{s:4:\"name\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:5:\"Title\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:30:\"The title of the current page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}}s:3:\"url\";a:3:{s:4:\"name\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:3:\"URL\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:28:\"The URL of the current page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:3:\"url\";}}s:7:\"metatag\";a:27:{s:6:\"author\";a:3:{s:4:\"name\";s:16:\"Advanced: Author\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:28:\"Define the author of a page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-author\";}s:13:\"cache_control\";a:3:{s:4:\"name\";s:23:\"Advanced: Cache control\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:140:\"Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Pragma meta tag.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-cache_control\";}s:13:\"canonical_url\";a:3:{s:4:\"name\";s:23:\"Advanced: Canonical URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:140:\"A link to the preferred page location or URL of the content of this page, to help eliminate duplicate content penalties from search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-canonical_url\";}s:7:\"expires\";a:3:{s:4:\"name\";s:17:\"Advanced: Expires\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:331:\"Control when the browser\'s internal cache of the current page should expire. The date must to be an <a href=\'https://www.csgnetwork.com/timerfc1123calc.html\'>RFC-1123</a>-compliant date string that is represented in Greenwich Mean Time (GMT), e.g. \'Thu, 01 Sep 2016 00:12:56 GMT\'. Set to \'0\' to stop the page being cached entirely.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:15:\"metatag-expires\";}s:9:\"generator\";a:3:{s:4:\"name\";s:19:\"Advanced: Generator\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:97:\"Describes the name and version number of the software or publishing tool used to create the page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-generator\";}s:13:\"geo_placename\";a:3:{s:4:\"name\";s:33:\"Advanced: Geographical place name\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:25:\"A location\'s formal name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-geo_placename\";}s:12:\"geo_position\";a:3:{s:4:\"name\";s:31:\"Advanced: Geographical position\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:261:\"Geo-spatial information in \'latitude; longitude\' format, e.g. \'50.167958; -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/Geographic_coordinate_system\' aria-label=\'see Wikipedia for details on the geographic coordinate system\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:20:\"metatag-geo_position\";}s:10:\"geo_region\";a:3:{s:4:\"name\";s:29:\"Advanced: Geographical region\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:130:\"A location\'s two-letter international country code, with an optional two-letter region, e.g. \'US-NH\' for New Hampshire in the USA.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:18:\"metatag-geo_region\";}s:6:\"google\";a:3:{s:4:\"name\";s:16:\"Advanced: Google\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:411:\"This meta tag communicates with Google. There are currently two directives supported: \'nositelinkssearchbox\' to not to show the sitelinks search box, and \'notranslate\' to ask Google not to offer a translation of the page. Both options may be added, just separate them with a comma. See <a href=\'https://support.google.com/webmasters/answer/79812?hl=en\'>meta tags that Google understands</a> for further details.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-google\";}s:4:\"icbm\";a:3:{s:4:\"name\";s:14:\"Advanced: ICBM\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:227:\"Geo-spatial information in \'latitude, longitude\' format, e.g. \'50.167958, -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/ICBM_address\' aria-label=\'see Wikipedia for details on ICBM addresses\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-icbm\";}s:9:\"image_src\";a:3:{s:4:\"name\";s:15:\"Advanced: Image\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:97:\"An image associated with this page, for use as a thumbnail in social networks and other services.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-image_src\";}s:4:\"next\";a:3:{s:4:\"name\";s:23:\"Advanced: Next page URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:65:\"Used for paginated content by providing URL with rel=\'next\' link.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-next\";}s:15:\"original_source\";a:3:{s:4:\"name\";s:25:\"Advanced: Original source\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:200:\"Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-original_source\";}s:6:\"pragma\";a:3:{s:4:\"name\";s:16:\"Advanced: Pragma\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:147:\"Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Cache-Control meta tag.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-pragma\";}s:4:\"prev\";a:3:{s:4:\"name\";s:27:\"Advanced: Previous page URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:65:\"Used for paginated content by providing URL with rel=\'prev\' link.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-prev\";}s:6:\"rating\";a:3:{s:4:\"name\";s:16:\"Advanced: Rating\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:454:\"Used to rate content for audience appropriateness. This tag has little known influence on search engine rankings, but can be used by browsers, browser extensions, and apps. The <a href=\'https://www.metatags.org/meta_name_rating\'>most common options</a> are general, mature, restricted, 14 years, safe for kids. If you follow the <a href=\'https://www.rtalabel.org/index.php?content=howto\'>RTA Documentation</a> you should enter RTA-5042-1996-1400-1577-RTA\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-rating\";}s:8:\"referrer\";a:3:{s:4:\"name\";s:25:\"Advanced: Referrer policy\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:280:\"Indicate to search engines and other page scrapers whether or not links should be followed. See <a href=\'https://w3c.github.io/webappsec/specs/referrer-policy/\'>the W3C specifications</a> for further details. Note: this serves the same purpose as the HTTP header by the same name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-referrer\";}s:7:\"refresh\";a:3:{s:4:\"name\";s:17:\"Advanced: Refresh\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:190:\"The number of seconds to wait before refreshing the page. May also force redirect to another page using the format \'5; url=https://example.com/\', which would be triggered after five seconds.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:15:\"metatag-refresh\";}s:13:\"revisit_after\";a:3:{s:4:\"name\";s:23:\"Advanced: Revisit After\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:193:\"Tell search engines when to index the page again. Very few search engines support this tag, it is more useful to use an <a href=\'https://www.drupal.org/project/xmlsitemap\'>XML Sitemap</a> file.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-revisit_after\";}s:6:\"rights\";a:3:{s:4:\"name\";s:16:\"Advanced: Rights\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:145:\"Details about intellectual property, such as copyright or trademarks; does not automatically protect the site\'s content or intellectual property.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-rights\";}s:6:\"robots\";a:3:{s:4:\"name\";s:16:\"Advanced: Robots\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:90:\"Provides search engines with specific directions for what to do when this page is indexed.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-robots\";}s:10:\"set_cookie\";a:3:{s:4:\"name\";s:20:\"Advanced: Set cookie\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:251:\"<a href=\'https://www.metatags.org/meta_http_equiv_set_cookie\'>Sets a cookie</a> on the visitor\'s browser. Can be in either NAME=VALUE format, or a more verbose format including the path and expiration date; see the link for full details on the syntax.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:18:\"metatag-set_cookie\";}s:9:\"shortlink\";a:3:{s:4:\"name\";s:23:\"Advanced: Shortlink URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:55:\"A brief URL, often created by a URL shortening service.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-shortlink\";}s:8:\"abstract\";a:3:{s:4:\"name\";s:20:\"Basic tags: Abstract\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:341:\"A brief and concise summary of the page\'s content, preferably 150 characters or less. Where as the description meta tag may be used by search engines to display a snippet about the page in search results, the abstract tag may be used to archive a summary about the page. This meta tag is <em>no longer</em> supported by major search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-abstract\";}s:11:\"description\";a:3:{s:4:\"name\";s:23:\"Basic tags: Description\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:206:\"A brief and concise summary of the page\'s content that is a maximum of 160 characters in length. The description meta tag may be used by search engines to display a snippet about the page in search results.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:19:\"metatag-description\";}s:8:\"keywords\";a:3:{s:4:\"name\";s:20:\"Basic tags: Keywords\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:120:\"A comma-separated list of keywords about the page. This meta tag is <em>no longer</em> supported by most search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-keywords\";}s:5:\"title\";a:3:{s:4:\"name\";s:22:\"Basic tags: Page title\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:437:\"The text to display in the title bar of a visitor\'s web browser when they view this page. This meta tag may also be used as the title of the page when a visitor bookmarks or favorites this page, or as the page title in a search engine result. It is common to append \'[site:name]\' to the end of this, so the site\'s name is automatically added. It is recommended that the title is no greater than 55 - 65 characters long, including spaces.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:13:\"metatag-title\";}}s:21:\"metatag-geo_placename\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:33:\"Advanced: Geographical place name\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2584;}}s:23:\"metatag-original_source\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:25:\"Advanced: Original source\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2633;}}s:14:\"metatag-rating\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:16:\"Advanced: Rating\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2654;}}s:14:\"metatag-author\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:16:\"Advanced: Author\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2549;}}s:21:\"metatag-canonical_url\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Advanced: Canonical URL\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2563;}}s:15:\"metatag-refresh\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:17:\"Advanced: Refresh\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2668;}}s:14:\"metatag-robots\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:16:\"Advanced: Robots\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2689;}}s:13:\"metatag-title\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:22:\"Basic tags: Page title\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2731;}}s:17:\"metatag-shortlink\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Advanced: Shortlink URL\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2703;}}s:16:\"metatag-keywords\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:20:\"Basic tags: Keywords\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2724;}}s:15:\"metatag-expires\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:17:\"Advanced: Expires\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2570;}}s:18:\"metatag-set_cookie\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:20:\"Advanced: Set cookie\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2696;}}s:18:\"metatag-geo_region\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:29:\"Advanced: Geographical region\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2598;}}s:12:\"metatag-icbm\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:14:\"Advanced: ICBM\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2612;}}s:17:\"metatag-generator\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:19:\"Advanced: Generator\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2577;}}s:19:\"metatag-description\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Basic tags: Description\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2717;}}s:21:\"metatag-cache_control\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Advanced: Cache control\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2556;}}s:14:\"metatag-pragma\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:16:\"Advanced: Pragma\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2640;}}s:12:\"metatag-next\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Advanced: Next page URL\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2626;}}s:21:\"metatag-revisit_after\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Advanced: Revisit After\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:2675;}}s:12:\"metatag-prev\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:27:\"Advanced: Previous page URL\";s:6:\"module\";s:7:\"me