('metatag_tags','a:27:{s:13:\"geo_placename\";a:11:{s:2:\"id\";s:13:\"geo_placename\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:23:\"Geographical place name\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:25:\"A location\'s formal name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:13:\"geo.placename\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:0;s:4:\"type\";s:5:\"label\";s:6:\"secure\";i:0;s:8:\"multiple\";b:0;s:5:\"class\";s:46:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\GeoPlacename\";s:8:\"provider\";s:7:\"metatag\";}s:15:\"original_source\";a:11:{s:2:\"id\";s:15:\"original_source\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:15:\"Original source\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:200:\"Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:15:\"original-source\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:4;s:4:\"type\";s:3:\"uri\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:48:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\OriginalSource\";s:8:\"provider\";s:7:\"metatag\";}s:6:\"rating\";a:11:{s:2:\"id\";s:6:\"rating\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:6:\"Rating\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:454:\"Used to rate content for audience appropri