8:\"advanced\";s:6:\"weight\";i:1;s:4:\"type\";s:3:\"uri\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:46:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\CanonicalUrl\";s:8:\"provider\";s:7:\"metatag\";}s:7:\"refresh\";a:11:{s:2:\"id\";s:7:\"refresh\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:7:\"Refresh\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:190:\"The number of seconds to wait before refreshing the page. May also force redirect to another page using the format \'5; url=https://example.com/\', which would be triggered after five seconds.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:7:\"refresh\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:41:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Refresh\";s:8:\"provider\";s:7:\"metatag\";}s:6:\"robots\";a:11:{s:2:\"id\";s:6:\"robots\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:6:\"Robots\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:90:\"Provides search engines with specific directions for what to do when this page is indexed.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:6:\"robots\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:1;s:4:\"type\";s:6:\"string\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:40:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Robots\";s:8:\"provider\";s:7:\"metatag\";}s:5:\"title\";a:12:{s:2:\"id\";s:5:\"title\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:10:\"Page title\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:437:\"The text to display in the title bar of a visitor\'s web browser when they view this page. This meta tag may also be used as the title of the page when a visitor bookmarks or favorites this page, or as the page title in a search engine result. It is common to append \'[site:name]\' to the end of this, so the site\'s name is automatically added. It is recommended that the title is no greater than 55 - 65 characters long, including spaces.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:5:\"title\";s:5:\"group\";s:5:\"basic\";s:6:\"weight\";i:-1;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:9:\"trimmable\";b:1;s:5:\"class\";s:39:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Title\";s:8:\"provider\";s:7:\"metatag\";}s:9:\"shortlink\";a:11:{s:2:\"id\";s:9:\"shortlink\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:13:\"Shortlink URL\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:55:\"A brief URL, often created by a URL shortening service.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:9:\"shortlink\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:1;s:4:\"type\";s:3:\"uri\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:43:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\ShortLink\";s:8:\"provider\";s:7:\"metatag\";}s:8:\"keywords\";a:11:{s:2:\"id\";s:8:\"keywords\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:8:\"Keywords\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:120:\"A comma-separated list of keywords about the page. This meta tag 