tions\";a:0:{}}s:4:\"name\";s:10:\"set-cookie\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:6:\"string\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:43:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\SetCookie\";s:8:\"provider\";s:7:\"metatag\";}s:10:\"geo_region\";a:11:{s:2:\"id\";s:10:\"geo_region\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:19:\"Geographical region\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:130:\"A location\'s two-letter international country code, with an optional two-letter region, e.g. \'US-NH\' for New Hampshire in the USA.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:10:\"geo.region\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:0;s:4:\"type\";s:5:\"label\";s:6:\"secure\";i:0;s:8:\"multiple\";b:0;s:5:\"class\";s:43:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\GeoRegion\";s:8:\"provider\";s:7:\"metatag\";}s:4:\"icbm\";a:11:{s:2:\"id\";s:4:\"icbm\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:4:\"ICBM\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:227:\"Geo-spatial information in \'latitude, longitude\' format, e.g. \'50.167958, -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/ICBM_address\' aria-label=\'see Wikipedia for details on ICBM addresses\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:4:\"icbm\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:0;s:4:\"type\";s:5:\"label\";s:6:\"secure\";i:0;s:8:\"multiple\";b:0;s:5:\"class\";s:38:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Icbm\";s:8:\"provider\";s:7:\"metatag\";}s:9:\"generator\";a:11:{s:2:\"id\";s:9:\"generator\";s