('entity_view:node:1:full:zh-hans:[languages:language_content]=zh-hans:[languages:language_interface]=zh-hans:[languages:language_url]=zh-hans:[theme]=itc_theme:[url.site]=https://itc-start.ddev.site:[user.permissions]=is-admin','O:31:\"Drupal\\Core\\Cache\\CacheRedirect\":3:{s:16:\"\0*\0cacheContexts\";a:8:{i:0;s:26:\"languages:language_content\";i:1;s:8:\"url.site\";i:2;s:22:\"languages:language_url\";i:3;s:28:\"languages:language_interface\";i:4;s:5:\"theme\";i:5;s:16:\"user.permissions\";i:6;s:24:\"user.roles:authenticated\";i:11;s:8:\"timezone\";}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;}',-1,1765157532.620,1,'','0'),
('entity_view:node:1:search_index:en:[languages:language_interface]=en:[theme]=itc_theme:[timezone]=Asia/Shanghai:[user.permissions]=d6b2bb804dbcb1862c52f3d78b6a364c29eda7d31395046de91c9f6dccd2104d','a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:24641:\"<h1>About Us - ITC</h1>\n<span>About Us - ITC</span>\n\n<span><span>itc-admin</span></span>\n\n<span><time datetime=\"2025-12-06T15:47:38+08:00\" title=\"Saturday, December 6, 2025 - 15:47\">Sat, 12/06/2025 - 15:47</time>\n</span>\n\n      <div>\n              <div>\n\n<div class=\"paragraph-section-text\">\n\n  <div class=\"bg-white py-[50px] px-[15px] md:py-[100px] md:px-[150px] text-center\">\n    <div class=\"max-w-[1200px] mx-auto\">\n              <h2 class=\"font-[\'Ubuntu\',sans-serif] font-bold text-[30px] leading-[36px] text-itc-black mb-0\">\n          \n            <div>Reimagining Your Digital Future Together</div>\n      \n        </h2>\n      \n              <div class=\"font-[\'Lato\',sans-serif] text-[16px] leading-[30px] text-itc-dark-gray mt-[30px] md:px-[97px]\">\n          \n            <div><p>IT Consultis is an award-winning Digital Transformation Consultancy in China and APAC, empowering the most ambitious Fortune 500 companies with the right strategy &amp; execution playbook leveraging MarTech, e-Commerce, and Omnichannel solutions to grow revenue and build customer loyalty.</p></div>\n      \n        </div>\n          </div>\n  </div>\n\n\n          \n    <div class=\"bg-itc-red text-white py-[50px] px-[15px] md:py-[100px] md:px-[150px] text-center relative\">\n      <div class=\"max-w-[1200px] mx-auto font-[\'Lato\',sans-serif] text-[16px] leading-[30px] md:px-[195px]\">\n        \n            <div><p>Our team consists of 60+ highly motivated talents from 14 different nationalities based in 3 countries across Asia, from Shanghai, China, to Saigon, Vietnam, and Singapore.</p></div>\n      \n      </div>\n    </div>\n  \n</div>\n</div>\n              <div><div class=\"paragraph-section-pillars bg-white py-[50px] px-[15px] md:py-[100px] md:px-[150px]\">\n  <div class=\"max-w-[1200px] mx-auto text-center\">\n\n              <h2 class=\"font-[\'Ubuntu\',sans-serif] font-bold text-[30px] leading-[36px] text-itc-black mb-0\">\n        \n            <div>The 4 Pillars to Realize Our Vision for Your Success</div>\n      \n      </h2>\n    \n              <div class=\"font-[\'Lato\',sans-serif] text-[16px] leading-[30px] text-itc-dark-gray mt-[30px] md:px-[97px] mb-[30px] md:mb-[50px] space-y-5 [&_p:not(:last-child)]:mb-5\">\n        \n            <div><p>ITC offers a wide range of strategy consulting and technology development services for various industries worldwide.&nbsp;<br>Ultimately, we help our clients develop the best strategies and playbook set-up along with the right digital enablers to achieve their objectives in China, Asia, and other markets.</p><p>Find your next success path with our combined strategic and technology expertis</p></div>\n      \n      </div>\n    \n        <div class=\"flex flex-wrap justify-center gap-[30px] text-left\">\n                                                                                                                                                                                                                                          <div class=\"w-full md:w-[calc(50%-15px)] lg:w-[calc(25%-23px)] flex-grow-0 flex-shrink-0\">\n            \n<div class=\"about-us_pillar bg-itc-light-gray rounded-[20px] py-[40px] px-[25px] pb-[30px] flex flex-col items-center text-center h-full\">\n\n      <div class=\"mb-[40px] h-[120px] w-full flex items-center justify-center\">\n      <div class=\"relative w-full h-full flex items-center justify-center [&>img]:max-h-full [&>img]:w-auto [&>img]:object-contain\">\n        \n            <div><div>\n  \n  \n  <div>\n    <div class=\"visually-hidden\">Image</div>\n              <div>  <img loading=\"lazy\" src=\"/sites/default/files/2025-12/Test.svg\" alt=\"Test svg\" />\n\n</div>\n          </div>\n\n</div>\n</div>\n      \n      </div>\n    </div>\n  \n      <h3 class=\"font-[\'Ubuntu\',sans-serif] font-bold text-[18px] leading-[26px] text-itc-black\">\n      \n            <div>Digital Transformation and Change Management</div>\n      \n    </h3>\n  \n</div>\n\n          </div>\n                                <div class=\"w-full md:w-[calc(50%-15px)] lg:w-[calc(25%-23px)] flex-grow-0 flex-shrink-0\">\n            \n<div class=\"about-us_pillar bg-itc-light-gray rounded-[20px] py-[40px] px-[25px] pb-[30px] flex flex-col items-center text-center h-full\">\n\n      <div class=\"mb-[40px] h-[120px] w-full flex items-center justify-center\">\n      <div class=\"relative w-full h-full flex items-center justify-center [&>img]:max-h-full [&>img]:w-auto [&>img]:object-contain\">\n        \n            <div><div>\n  \n  \n  <div>\n    <div class=\"visually-hidden\">Image</div>\n              <div>  <img loading=\"lazy\" src=\"/sites/default/files/2025-12/Test.svg\" alt=\"Test svg\" />\n\n</div>\n          </div>\n\n</div>\n</div>\n      \n      </div>\n    </div>\n  \n      <h3 class=\"font-[\'Ubuntu\',sans-serif] font-bold text-[18px] leading-[26px] text-itc-black\">\n      \n            <div>Digital Transformation Talent Augmentation</div>\n      \n    </h3>\n  \n</div>\n\n          </div>\n                                <div class=\"w-full md:w-[calc(50%-15px)] lg:w-[calc(25%-23px)] flex-grow-0 flex-shrink-0\">\n            \n<div class=\"about-us_pillar bg-itc-light-gray rounded-[20px] py-[40px] px-[25px] pb-[30px] flex flex-col items-center text-center h-full\">\n\n      <div class=\"mb-[40px] h-[120px] w-full flex items-center justify-center\">\n      <div class=\"relative w-full h-full flex items-center justify-center [&>img]:max-h-full [&>img]:w-auto [&>img]:object-contain\">\n        \n            <div><div>\n  \n  \n  <div>\n    <div class=\"visually-hidden\">Image</div>\n              <div>  <img loadi