INSERT INTO `paragraph__field_text_in_background` VALUES
('section_text',0,1,423,'en',0,'<p>Our team consists of 60+ highly motivated talents from 14 different nationalities based in 3 countries across Asia, from Shanghai, China, to Saigon, Vietnam, and Singapore.</p>','basic_html'),
('section_text',0,1,423,'zh-hans',0,'<p>我们的团队由来自 14 个不同国家的 60 多名积极进取的人才组成, 分布在亚洲的 3 个国家，从中国上海到越南胡志明和新加坡.</p>','basic_html');
