INSERT INTO `paragraph_revision__field_description` VALUES
('section_text',0,1,1,'en',0,'<p>IT Consultis is an award-winning Digital Transformation Consultancy in China and APAC, empowering the most ambitious Fortune 500 companies with the right strategy &amp; execution playbook leveraging MarTech, e-Commerce, and Omnichannel solutions to grow revenue and build customer loyalty.</p>','basic_html'),
