INSERT INTO `paragraph_revision__field_text_in_background` VALUES
('section_text',0,1,1,'en',0,'<p>Our team consists of 60+ highly motivated talents from 14 different nationalities based in 3 countries across Asia, from Shanghai, China, to Saigon, Vietnam, and Singapore.</p>','basic_html'),
('section_text',0,1,7,'en',0,'<p>Our team consists of 60+ highly motivated talents from 14 different nationalities based in 3 countries across Asia, from Shanghai, China, to Saigon, Vietnam, and Singapore.</p>','basic_html'),
('section_text',0,1,25,'en',0,'<p>我们的团队由来自 14 个不同国家的 60 多名积极进取的人才组成, 分布在亚洲的 3 个国家，从中国上海到越南胡志明和新加坡.</p>','basic_html'),
('section_text',0,1,43,'en',0,'<p>IT Consultis is an award-winning Digital Transformation Consultancy in China and APAC, empowering the most ambitious Fortune 500 companies with the right strategy &amp; execution playbook leveraging MarTech, e-Commerce, and Omnichannel solutions to grow revenue and build customer loyalty.</p>','basic_html'),
